import React, { useEffect, useState } from 'react'
import { createRoot } from 'react-dom/client'
import { api } from './services/api'
import './styles.css'
import './projection.css'
import './balance.css'
import './payment.css'
import './transactions.css'

const formatCurrency = value => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(Number(value) || 0)
const money = formatCurrency
const signedMoney = (value, positive = '+') => `${Number(value) < 0 ? '-' : positive} ${formatCurrency(Math.abs(Number(value) || 0))}`
const errorText = error => error?.message || 'Não foi possível concluir a operação.'
const parseAmount = value => { const normalized = String(value).trim().replace(',', '.'); if (!normalized || !/^\d+(\.\d{1,2})?$/.test(normalized)) return NaN; return Number(normalized) }
const addMonths = (date, months) => { if (!date) return ''; const [year, month, day] = date.slice(0, 10).split('-').map(Number); const result = new Date(Date.UTC(year, month - 1 + months, 1)); const lastDay = new Date(Date.UTC(result.getUTCFullYear(), result.getUTCMonth() + 1, 0)).getUTCDate(); result.setUTCDate(Math.min(day, lastDay)); return result.toISOString().slice(0, 10) }
const formatDate = date => date ? new Date(`${date.slice(0, 10)}T12:00:00`).toLocaleDateString('pt-BR') : 'Sem data informada'

function App() {
  const [summary, setSummary] = useState(null)
  const [commitments, setCommitments] = useState([])
  const [categories, setCategories] = useState([])
  const [searchInput, setSearchInput] = useState('')
  const [search, setSearch] = useState('')
  const [filters, setFilters] = useState({ category: '', priority: '', status: '', coverage: '', payment: '', deficit: false, payable: false, sort: 'priority' })
  const [collapsed, setCollapsed] = useState({})
  const [categoryDialog, setCategoryDialog] = useState(null)
  const [deleteDialog, setDeleteDialog] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [notice, setNotice] = useState('')
  const [preview, setPreview] = useState(null)
  const [modal, setModal] = useState(false)
  const [editing, setEditing] = useState(null)
  const [balanceModal, setBalanceModal] = useState(false)
  const [filtersOpen, setFiltersOpen] = useState(false)
  const [incomes, setIncomes] = useState([])
  const [recurringIncomes, setRecurringIncomes] = useState([])
  const [incomeDialog, setIncomeDialog] = useState(false)
  const [incomeDelete, setIncomeDelete] = useState(null)
  const [projection, setProjection] = useState(null)
  const [projectionMonths, setProjectionMonths] = useState(Number(localStorage.getItem('aloca-projection-months') || 12))

  const refresh = async () => {
    setLoading(true); setError('')
    try { const [nextSummary, nextCommitments, nextCategories, nextIncomes, nextRecurring, nextProjection] = await Promise.all([api.summary(), api.commitments(), api.categories(), api.incomes(), api.recurringIncomes(), api.projection(projectionMonths)]); setSummary(nextSummary); setCommitments(nextCommitments); setCategories(nextCategories); setIncomes(nextIncomes.items || []); setRecurringIncomes(nextRecurring || []); setProjection(nextProjection) }
    catch (e) { setError(errorText(e)) } finally { setLoading(false) }
  }
  useEffect(() => { refresh() }, [projectionMonths])
  useEffect(() => { const timer = setTimeout(() => setSearch(searchInput.trim().toLowerCase()), 250); return () => clearTimeout(timer) }, [searchInput])
  useEffect(() => {
    if (!filtersOpen) return undefined
    const closeOnEscape = event => { if (event.key === 'Escape') setFiltersOpen(false) }
    document.addEventListener('keydown', closeOnEscape)
    document.body.style.overflow = 'hidden'
    return () => { document.removeEventListener('keydown', closeOnEscape); document.body.style.overflow = '' }
  }, [filtersOpen])

  const filtered = commitments.filter(item => {
    const coverage = item.remainingInstallments === 0 ? 'full' : item.allocatedAmount <= 0 ? 'none' : item.allocatedAmount >= item.installmentAmount ? 'next' : 'partial'
    const payment = item.paidInstallments === 0 ? 'none' : item.isCompleted ? 'done' : 'progress'
    return (!search || item.name.toLowerCase().includes(search)) && (!filters.category || item.categoryId === filters.category) && (!filters.priority || String(item.priority) === filters.priority) && (!filters.status || (filters.status === 'completed' ? item.isCompleted : !item.isCompleted)) && (!filters.coverage || coverage === filters.coverage) && (!filters.payment || payment === filters.payment) && (!filters.deficit || item.missingForFullCoverage > 0) && (!filters.payable || item.allocatedAmount >= item.installmentAmount && !item.isCompleted)
  }).sort((a, b) => { const c = a.categoryName || 'Sem categoria'; const d = b.categoryName || 'Sem categoria'; if (filters.sort === 'name') return a.name.localeCompare(b.name); if (filters.sort === 'total') return b.totalAmount - a.totalAmount; if (filters.sort === 'remaining') return b.remainingAmount - a.remainingAmount; if (filters.sort === 'next') return a.missingForNextInstallment - b.missingForNextInstallment; if (filters.sort === 'progress') return (b.paidInstallments / b.totalInstallments) - (a.paidInstallments / a.totalInstallments); if (filters.sort === 'category') return c.localeCompare(d) || a.name.localeCompare(b.name); return a.priority - b.priority || a.name.localeCompare(b.name) })
  const groups = filtered.reduce((acc, item) => { const key = item.categoryId || 'none'; (acc[key] ||= []).push(item); return acc }, {})
  const clearFilters = () => { setSearchInput(''); setFilters({ category: '', priority: '', status: '', coverage: '', payment: '', deficit: false, payable: false, sort: 'priority' }) }
  const activeFilterCount = ['category', 'priority', 'status', 'coverage', 'payment'].filter(key => filters[key]).length + (filters.deficit ? 1 : 0) + (filters.payable ? 1 : 0) + (filters.sort !== 'priority' ? 1 : 0)
  const editCategory = category => setCategoryDialog(category)
  const deleteCategory = category => setDeleteDialog(category)

  const run = async action => { setError(''); setNotice(''); try { await action(); await refresh(); setNotice('Alterações salvas com sucesso.') } catch (e) { setError(errorText(e)) } }
  const openDistribution = async () => { setError(''); try { setPreview(await api.preview()); setModal(true) } catch (e) { setError(errorText(e)) } }
  const distribute = () => run(async () => { await api.distribute(); setModal(false); setPreview(null) })

  return <div className="app-shell">
    <header className="topbar"><div><span className="eyebrow">CONTROLE FINANCEIRO</span><h1>Aloca</h1></div><button className="primary" onClick={openDistribution}>Distribuir saldo</button></header>
    <main>
      {error && <div className="alert error">{error}</div>}{notice && <div className="alert success">{notice}</div>}
      <section className="hero"><div><span className="eyebrow">VISÃO GERAL</span><h2>Seu dinheiro, com destino claro.</h2><p>O saldo livre considera tudo que já está virtualmente comprometido.</p></div><div className="hero-mark">↗</div></section>
      {loading ? <div className="loading">Carregando sua vida financeira…</div> : <>
        <section className="summary-grid">
          <Metric label="Saldo real" value={money(summary?.balance)} tone="dark" caption={`Entradas ${money(summary?.totalIncome)} · Saídas ${money(summary?.totalExpense)}`} action={<button className="metric-action" onClick={() => setBalanceModal(true)}>{summary?.initialBalance > 0 ? 'Editar saldo inicial' : 'Informar saldo inicial'}</button>} />
          <Metric label="Comprometido" value={money(summary?.allocatedAmount)} caption="Reservas virtuais ativas" />
          <Metric label="Saldo livre" value={money(summary?.freeBalance)} tone="green" caption="Disponível para novas alocações" />
          <Metric label="Déficit de cobertura" value={money(summary?.allocationDeficit)} tone={summary?.allocationDeficit > 0 ? 'red' : 'soft'} caption={summary?.allocationDeficit > 0 ? 'Valor que ainda falta reservar.' : 'Todos os compromissos estão cobertos'} />
        </section>
        <FinancialProjectionChart data={projection} period={projectionMonths} onPeriodChange={value => { localStorage.setItem('aloca-projection-months', value); setProjectionMonths(value) }} />
        <IncomeSection incomes={incomes} recurringIncomes={recurringIncomes} categories={categories} onCreate={() => setIncomeDialog(true)} onDelete={income => setIncomeDelete(income)} onRefresh={refresh} onRecurringDeleted={() => setNotice('Entrada recorrente excluída com sucesso.')} />
        <section className="section-heading"><div><span className="eyebrow">PLANEJAMENTO</span><h2>Compromissos financeiros</h2><small>{filtered.length} de {commitments.length} encontrados</small></div><div className="section-actions"><button className="secondary" onClick={() => setFiltersOpen(true)}>Filtros{activeFilterCount ? ` (${activeFilterCount})` : ''}</button><button className="primary" onClick={() => setEditing({})}>Novo compromisso</button></div></section>
        <CommitmentFilters search={searchInput} setSearch={setSearchInput} onOpenFilters={() => setFiltersOpen(true)} onCreateCategory={async name => { await api.createCategory(name); await refresh() }} />
        {commitments.length === 0 ? <div className="empty"><strong>Nenhum compromisso ainda</strong><span>Crie um compromisso para começar a organizar seu saldo.</span></div> : filtered.length === 0 ? <div className="empty"><strong>Nenhum resultado encontrado</strong><span>Ajuste os filtros ou limpe a busca.</span></div> : <div className="commitment-groups">{Object.entries(groups).map(([key, items]) => { const category = categories.find(x => x.id === key); const pending = items.reduce((sum, x) => sum + x.remainingAmount, 0); return <section className="commitment-group" key={key}><button className="group-header" onClick={() => setCollapsed(x => ({ ...x, [key]: !x[key] }))}><span><strong>{category?.name || 'Sem categoria'}</strong><small>{items.length} compromisso(s) · {money(pending)} pendente</small></span><span>{collapsed[key] ? '＋' : '−'}</span></button>{!collapsed[key] && <div className="commitment-list">{items.map(item => <CommitmentCard key={item.id} item={item} availableBalance={summary?.freeBalance ?? 0} categories={categories} onChange={refresh} onEdit={() => setEditing(item)} onDelete={() => run(() => api.deleteCommitment(item.id))} />)}</div>}</section> })}</div>}
      </>}
    </main>
    {editing && <CommitmentModal item={editing} categories={categories} onClose={() => setEditing(null)} onSaved={() => { setEditing(null); run(async () => {}) }} />}
    {balanceModal && <InitialBalanceModal value={summary?.initialBalance ?? 0} onClose={() => setBalanceModal(false)} onSaved={() => { setBalanceModal(false); refresh(); setNotice('Saldo inicial atualizado.') }} />}
    {incomeDialog && <IncomeModal categories={categories} onClose={() => setIncomeDialog(false)} onSaved={() => { setIncomeDialog(false); run(async () => {}) }} />}
    {incomeDelete && <ConfirmModal title="Excluir entrada?" message={`Esta ação não poderá ser desfeita. A entrada “${incomeDelete.description}” de ${money(incomeDelete.amount)} será removida do saldo real.`} onClose={() => setIncomeDelete(null)} onConfirm={() => run(async () => { await api.deleteIncome(incomeDelete.id); setIncomeDelete(null) })} />}
    {modal && <DistributionModal preview={preview} onClose={() => setModal(false)} onConfirm={distribute} />}
    {filtersOpen && <FilterDrawer filters={filters} setFilters={setFilters} categories={categories} onClear={clearFilters} onClose={() => setFiltersOpen(false)} onEditCategory={editCategory} onDeleteCategory={deleteCategory} />}
    {categoryDialog && <CategoryModal category={categoryDialog} onClose={() => setCategoryDialog(null)} onSaved={() => { setCategoryDialog(null); run(async () => {}) }} />}
    {deleteDialog && <ConfirmModal title="Excluir categoria?" message={`A categoria ${deleteDialog.name} será removida. Compromissos vinculados ficarão sem categoria.`} onClose={() => setDeleteDialog(null)} onConfirm={() => run(async () => { await api.deleteCategory(deleteDialog.id); setDeleteDialog(null) })} />}
  </div>
}

function Metric({ label, value, caption, tone = '', action }) { return <article className={`metric ${tone}`}><span>{label}</span><strong>{value}</strong><small>{caption}</small>{action}</article> }

function FinancialProjectionChart({ data, period, onPeriodChange }) {
  const [view, setView] = useState(localStorage.getItem('aloca-projection-view') || 'line')
  const [selected, setSelected] = useState(null)
  if (!data) return null
  const months = data.months || [], width = Math.max(680, months.length * 82), height = 300, left = 66, right = 18, top = 18, bottom = 42
  if (!months.length) return null
  const values = months.flatMap(x => [Number(x.projectedBalance), Number(x.totalIncome), -Number(x.totalExpense), 0])
  const rawMin = Math.min(...values), rawMax = Math.max(...values), range = rawMax - rawMin || Math.max(Math.abs(rawMax), 1)
  const stepMagnitude = 10 ** Math.floor(Math.log10(range / 6)), normalizedStep = (range / 6) / stepMagnitude
  const step = stepMagnitude * (normalizedStep <= 1 ? 1 : normalizedStep <= 2 ? 2 : normalizedStep <= 2.5 ? 2.5 : normalizedStep <= 5 ? 5 : 10)
  const min = Math.floor(rawMin / step) * step, max = Math.ceil(rawMax / step) * step, tickCount = Math.max(1, Math.round((max - min) / step))
  const x = i => left + (width - left - right) * (months.length <= 1 ? 0.5 : i / (months.length - 1)), y = v => top + (max - v) / (max - min || 1) * (height - top - bottom)
  const ticks = Array.from({ length: tickCount + 1 }, (_, i) => max - i * step)
  const points = months.map((m, i) => `${x(i)},${y(m.projectedBalance)}`).join(' '), moneyShort = v => formatCurrency(v).replace(/,00$/, ''), label = v => { const date = new Date(`${v}T12:00:00`); const month = date.toLocaleDateString('pt-BR', { month: 'short' }).replace('.', ''); return date.getFullYear() !== new Date().getFullYear() ? `${month} ${String(date.getFullYear()).slice(-2)}` : month }
  const choose = value => { localStorage.setItem('aloca-projection-view', value); setView(value) }
  const showZero = min <= 0 && max >= 0, balanceDelta = Number(data.finalProjectedBalance) - Number(data.currentBalance), incomeOccurrences = months.reduce((sum, month) => sum + (month.incomes?.length || 0), 0)
  const legend = view === 'line' ? [['balance', 'Saldo projetado']] : view === 'area' ? [['balance', 'Saldo projetado']] : [['income', 'Entradas'], ['expense', 'Saídas'], ['balance', 'Saldo projetado']]
  return <section className="projection-section"><div className="projection-heading"><div><span className="eyebrow">PROJEÇÃO FINANCEIRA</span><h2>Projeção de saldo</h2><p>Estimativa baseada nas suas entradas e compromissos cadastrados.</p></div><div className="projection-controls"><label>Período<select aria-label="Período da projeção" value={period} onChange={e => onPeriodChange(Number(e.target.value))}><option value="3">3 meses</option><option value="6">6 meses</option><option value="12">12 meses</option><option value="24">24 meses</option></select></label><label>Visualização<select aria-label="Visualização da projeção" value={view} onChange={e => choose(e.target.value)}><option value="line">Linha</option><option value="bar">Barras</option><option value="area">Área</option></select></label></div></div><div className="projection-stats"><span>Saldo atual<strong>{money(data.currentBalance)}</strong></span><span>Saldo projetado<strong className={data.finalProjectedBalance < 0 ? 'negative' : ''}>{money(data.finalProjectedBalance)}</strong><small className={balanceDelta < 0 ? 'negative' : 'positive'}>{balanceDelta < 0 ? '↓' : '↑'} {money(Math.abs(balanceDelta))} no período</small></span><span>Entradas previstas<strong className="positive">{signedMoney(data.totalProjectedIncome)}</strong><small>{incomeOccurrences} {incomeOccurrences === 1 ? 'entrada prevista' : 'entradas previstas'}</small></span><span>Saídas previstas<strong className="negative">{signedMoney(data.totalProjectedExpense, '-')}</strong></span></div><div className="projection-chart-wrap" onClick={() => setSelected(null)}><div className="projection-scroll"><svg className="projection-chart" role="img" aria-label={`Projeção de saldo em ${months.length} meses`} viewBox={`0 0 ${width} ${height}`}>{ticks.map(tick => <g key={tick}><line className="projection-grid" x1={left} x2={width - right} y1={y(tick)} y2={y(tick)} /><text className="projection-axis" x="4" y={y(tick) + 4}>{moneyShort(tick)}</text></g>)}{showZero && <line className="projection-zero" x1={left} x2={width - right} y1={y(0)} y2={y(0)} />}{view === 'area' && <polygon className="projection-area" points={`${x(0)},${y(0)} ${points} ${x(months.length - 1)},${y(0)}`} />}{view !== 'bar' && <polyline className="projection-line" points={points} />}{view === 'bar' && <polyline className="projection-line projection-bar-balance" points={points} />}{months.map((m, i) => <g className={`projection-month ${selected === i ? 'is-selected' : ''}`} key={m.month} tabIndex="0" role="button" aria-label={`Abrir detalhes de ${label(m.month)}`} onMouseEnter={() => setSelected(i)} onFocus={() => setSelected(i)} onClick={e => { e.stopPropagation(); setSelected(selected === i ? null : i) }} onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setSelected(selected === i ? null : i) } }}>{view === 'bar' && <><rect className="projection-income-bar" x={x(i) - 20} y={y(Math.max(0, Number(m.totalIncome)))} width="16" height={Math.abs(y(0) - y(Number(m.totalIncome)))} /><rect className="projection-expense-bar" x={x(i) + 4} y={y(0)} width="16" height={Math.abs(y(0) - y(-Number(m.totalExpense)))} /></>}{view !== 'bar' && <circle className="projection-hit" cx={x(i)} cy={y(m.projectedBalance)} r="13" />}{view === 'bar' && <circle className="projection-hit projection-bar-hit" cx={x(i)} cy={y(m.projectedBalance)} r="10" />}<circle className="projection-point" cx={x(i)} cy={y(m.projectedBalance)} r={selected === i ? 5 : 3} /><text className="projection-label" x={x(i)} y={height - 10} textAnchor="middle">{label(m.month)}</text></g>)}</svg></div>{selected != null && <ProjectionTooltip item={months[selected]} onClose={() => setSelected(null)} />}</div><div className="projection-legend">{legend.map(([kind, text]) => <span key={kind}><i className={`legend-${kind}`} />{text}</span>)}</div></section>
}

function ProjectionTooltip({ item, onClose }) { const title = new Date(`${item.month}T12:00:00`).toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' }).toUpperCase(); const result = Number(item.totalIncome) - Number(item.totalExpense); const rows = (items, negative) => items?.length ? items.map(x => <div className="tooltip-row" key={x.id}><span>{x.description}<small>{x.date ? formatDate(x.date) : ''}{x.installment ? ` · Parcela ${x.installment}/${x.totalInstallments}` : x.recurring ? ' · Recorrente' : x.category ? ` · ${x.category}` : ' · Avulsa'}</small></span><b className={negative ? 'negative' : 'positive'}>{signedMoney(negative ? -Number(x.amount) : Number(x.amount))}</b></div>) : <small>Nenhuma movimentação prevista.</small>; return <div className="projection-tooltip" role="dialog" aria-label={`Detalhes de ${title}`}><button className="projection-close" aria-label="Fechar detalhes" onClick={onClose}>×</button><strong>{title}</strong><div className="tooltip-summary"><span>Saldo inicial <b>{money(item.openingBalance)}</b></span><span>Entradas <b className="positive">{signedMoney(item.totalIncome)}</b></span><span>Saídas <b className="negative">{signedMoney(-Number(item.totalExpense))}</b></span><span>Resultado do mês <b className={result < 0 ? 'negative' : 'positive'}>{signedMoney(result)}</b></span><span>Saldo projetado <b className={item.projectedBalance < 0 ? 'negative' : ''}>{money(item.projectedBalance)}</b></span></div><div className="tooltip-group"><em>ENTRADAS</em>{rows(item.incomes, false)}</div><div className="tooltip-group"><em>SAÍDAS</em>{rows(item.expenses, true)}</div></div> }

function InitialBalanceModal({ value, onClose, onSaved }) {
  const [amount, setAmount] = useState(String(value ?? 0)); const [error, setError] = useState(''); const [saving, setSaving] = useState(false)
  const save = async e => { e.preventDefault(); const numeric = Number(amount); if (!Number.isFinite(numeric) || numeric < 0) { setError('Informe um valor válido maior ou igual a zero.'); return } setSaving(true); setError(''); try { await api.updateSettings(numeric); onSaved() } catch (e) { setError(errorText(e)) } finally { setSaving(false) } }
  return <div className="modal-backdrop"><form className="modal" onSubmit={save}><div className="modal-head"><div><span className="eyebrow">CONFIGURAÇÃO FINANCEIRA</span><h2>{value > 0 ? 'Editar saldo inicial' : 'Informar saldo inicial'}</h2></div><button type="button" className="icon-button" onClick={onClose}>×</button></div><p className="modal-copy">Informe quanto você já possui antes de registrar novas movimentações. Isso não cria uma transação.</p>{error && <div className="alert error">{error}</div>}<label>Saldo inicial<input autoFocus required type="number" min="0" step="0.01" placeholder="1500,00" value={amount} onChange={e => setAmount(e.target.value)} /></label><div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary" disabled={saving}>Salvar saldo inicial</button></div></form></div>
}

function CategoryModal({ category, onClose, onSaved }) { const [name, setName] = useState(category?.name || ''); const [error, setError] = useState(''); const save = async e => { e.preventDefault(); if (!name.trim()) { setError('Informe o nome da categoria.'); return } try { await api.updateCategory(category.id, name.trim()); onSaved() } catch (e) { setError(errorText(e)) } }; return <div className="modal-backdrop"><form className="modal" onSubmit={save}><h2>Editar categoria</h2>{error && <div className="alert error">{error}</div>}<label>Nome<input autoFocus value={name} onChange={e => setName(e.target.value)} /></label><div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary">Salvar</button></div></form></div> }
function ConfirmModal({ title, message, onClose, onConfirm, confirmLabel = 'Confirmar', busy = false, error = '' }) { return <div className="modal-backdrop"><div className="modal"><h2>{title}</h2><p className="modal-copy">{message}</p>{error && <div className="alert error">{error}</div>}<div className="modal-actions"><button className="secondary" onClick={onClose} disabled={busy}>Cancelar</button><button className="primary" onClick={onConfirm} disabled={busy}>{busy ? 'Excluindo…' : confirmLabel}</button></div></div></div> }

function RegularIncomeSection({ incomes, categories, onCreate, onDelete }) {
  const [search, setSearch] = useState(''); const [category, setCategory] = useState(''); const [period, setPeriod] = useState(''); const [sort, setSort] = useState('date-desc')
  const items = incomes.filter(item => (!search || item.description.toLowerCase().includes(search.toLowerCase())) && (!category || item.categoryId === category) && (!period || item.date.slice(0, 7) === period)).sort((a, b) => sort === 'amount-desc' ? b.amount - a.amount : sort === 'amount-asc' ? a.amount - b.amount : sort === 'date-asc' ? a.date.localeCompare(b.date) : b.date.localeCompare(a.date))
  return <section className="income-section"><div className="income-heading"><div><span className="eyebrow">MOVIMENTAÇÕES</span><h2>Entradas</h2><small>{items.length} entrada(s) encontrada(s)</small></div><button className="primary" onClick={onCreate}>Nova entrada</button></div><div className="income-filters"><input aria-label="Pesquisar entradas" placeholder="Pesquisar por descrição..." value={search} onChange={e => setSearch(e.target.value)} /><select aria-label="Filtrar por categoria" value={category} onChange={e => setCategory(e.target.value)}><option value="">Todas as categorias</option>{categories.map(x => <option key={x.id} value={x.id}>{x.name}</option>)}</select><input aria-label="Filtrar por período" type="month" value={period} onChange={e => setPeriod(e.target.value)} /><select aria-label="Ordenar entradas" value={sort} onChange={e => setSort(e.target.value)}><option value="date-desc">Mais recentes</option><option value="date-asc">Mais antigas</option><option value="amount-desc">Maior valor</option><option value="amount-asc">Menor valor</option></select></div>{items.length ? <div className="income-list">{items.map(item => <article className="income-row" key={item.id}><div className="income-icon">↗</div><div className="income-info"><strong>{item.description}</strong><span>{item.categoryName} · {new Date(`${item.date}T12:00:00`).toLocaleDateString('pt-BR')}</span></div><strong className="income-amount">+ {money(item.amount)}</strong><button className="icon-button danger-text" onClick={() => onDelete(item)} aria-label={`Excluir entrada ${item.description}`}>×</button></article>)}</div> : <div className="empty income-empty"><strong>{incomes.length ? 'Nenhuma entrada encontrada' : 'Nenhuma entrada ainda'}</strong><span>{incomes.length ? 'Ajuste os filtros para encontrar uma entrada.' : 'Registre sua primeira entrada para atualizar seu saldo.'}</span>{!incomes.length && <button className="secondary" onClick={onCreate}>Criar primeira entrada</button>}</div>}</section>
}

function IncomeSection({ incomes, recurringIncomes, categories, onCreate, onDelete, onRefresh, onRecurringDeleted }) {
  const [tab, setTab] = useState('all')
  const [recurringDialog, setRecurringDialog] = useState(false)
  const visible = tab === 'recurring' ? [] : incomes
  return <section className="income-section"><div className="income-heading"><div><span className="eyebrow">MOVIMENTAÇÕES</span><h2>Entradas</h2><small>{tab === 'recurring' ? `${recurringIncomes.length} recorrência(s)` : `${incomes.length} entrada(s) recentes`}</small></div><div className="income-actions"><button className="secondary" onClick={() => setRecurringDialog(true)}>Nova recorrente</button><button className="primary" onClick={onCreate}>Nova entrada</button></div></div><div className="income-tabs" role="tablist"><button className={tab === 'all' ? 'active' : ''} onClick={() => setTab('all')}>Todas</button><button className={tab === 'recurring' ? 'active' : ''} onClick={() => setTab('recurring')}>Recorrentes <span>{recurringIncomes.length}</span></button></div>{tab === 'all' && <RegularIncomeSection incomes={visible} categories={categories} onCreate={onCreate} onDelete={onDelete} />}{tab === 'recurring' && <RecurringIncomeList items={recurringIncomes} onRefresh={onRefresh} onDeleted={onRecurringDeleted} />}{recurringDialog && <RecurringIncomeModal categories={categories} onClose={() => setRecurringDialog(false)} onSaved={() => { setRecurringDialog(false); onRefresh() }} />}</section>
}

const frequencyLabels = { Weekly: 'Semanal', Fortnightly: 'Quinzenal', Monthly: 'Mensal', Bimonthly: 'Bimestral', Quarterly: 'Trimestral', Semiannual: 'Semestral', Annual: 'Anual' }
function RecurringIncomeList({ items, onRefresh, onDeleted }) {
  const [query, setQuery] = useState(''); const [status, setStatus] = useState('all'); const [pendingDelete, setPendingDelete] = useState(null); const [deletingId, setDeletingId] = useState(null); const [deleteError, setDeleteError] = useState('')
  const filtered = items.filter(x => (!query || x.description.toLowerCase().includes(query.toLowerCase())) && (status === 'all' || (status === 'active' ? x.isActive : !x.isActive)))
  const act = async (fn, message) => { await fn(); await onRefresh() }
  const deleteRecurring = async () => { setDeletingId(pendingDelete.id); setDeleteError(''); try { await api.deleteRecurringIncome(pendingDelete.id); setPendingDelete(null); await onRefresh(); onDeleted() } catch (e) { setDeleteError(errorText(e)) } finally { setDeletingId(null) } }
  return <div className="recurring-panel"><div className="recurring-tools"><input aria-label="Pesquisar recorrências" placeholder="Pesquisar recorrência..." value={query} onChange={e => setQuery(e.target.value)} /><select aria-label="Filtrar recorrências" value={status} onChange={e => setStatus(e.target.value)}><option value="all">Todos os status</option><option value="active">Ativas</option><option value="paused">Pausadas</option></select></div>{filtered.length ? <div className="recurring-list">{filtered.map(item => <article className="recurring-row" key={item.id}><div className="recurring-main"><strong>{item.description}</strong><span>{money(item.amount)} · {item.categoryName} · {frequencyLabels[item.frequency]}</span></div><div className="recurring-next"><small>Próxima ocorrência</small><strong>{item.nextOccurrence ? new Date(`${item.nextOccurrence}T12:00:00`).toLocaleDateString('pt-BR') : 'Sem próximas'}</strong></div><span className={`recurring-status ${item.isActive ? 'active' : 'paused'}`}>{item.isActive ? 'Ativa' : 'Pausada'}</span><div className="recurring-actions">{item.occurrences?.find(x => x.status === 'Planned') && <button className="primary" onClick={() => act(() => api.receiveRecurringOccurrence(item.occurrences.find(x => x.status === 'Planned').id))}>Marcar como recebida</button>}{item.isActive ? <button className="secondary" onClick={() => act(() => api.pauseRecurringIncome(item.id))}>Pausar</button> : <button className="primary" onClick={() => act(() => api.activateRecurringIncome(item.id))}>Reativar</button>}<button className="icon-button danger-text" disabled={deletingId !== null} aria-label={`Excluir recorrência ${item.description}`} onClick={() => { setDeleteError(''); setPendingDelete(item) }}>×</button></div></article>)}</div> : <div className="empty"><strong>Nenhuma recorrência encontrada</strong><span>Cadastre salário, aluguel recebido ou outra entrada periódica.</span></div>}{pendingDelete && <ConfirmModal title="Excluir recorrência?" message="Essa ação removerá esta recorrência e não poderá ser desfeita." confirmLabel="Excluir" busy={deletingId === pendingDelete.id} error={deleteError} onClose={() => { if (!deletingId) setPendingDelete(null) }} onConfirm={deleteRecurring} />}</div>
}

function RecurringIncomeModal({ categories, onClose, onSaved }) {
  const [form, setForm] = useState({ description: '', amount: '', categoryId: categories[0]?.id || '', frequency: 'Monthly', startDate: new Date().toISOString().slice(0, 10), endDate: '', dayOfMonth: new Date().getDate() }); const [error, setError] = useState(''); const update = (key, value) => setForm(x => ({ ...x, [key]: value }))
  const save = async e => { e.preventDefault(); if (!form.description.trim() || !form.amount || !form.categoryId || !form.startDate) return setError('Preencha descrição, valor, categoria e início.'); if (form.endDate && form.endDate < form.startDate) return setError('A data final deve ser igual ou posterior ao início.'); try { await api.createRecurringIncome({ ...form, amount: parseAmount(form.amount), dayOfMonth: form.frequency === 'Monthly' ? Number(form.dayOfMonth) : null, endDate: form.endDate || null }); onSaved() } catch (e) { setError(errorText(e)) } }
  return <div className="modal-backdrop"><form className="modal" onSubmit={save}><div className="modal-head"><div><span className="eyebrow">ENTRADA RECORRENTE</span><h2>Nova recorrência</h2></div><button type="button" className="icon-button" onClick={onClose} aria-label="Fechar">×</button></div>{error && <div className="alert error">{error}</div>}<label>Descrição<input autoFocus required value={form.description} onChange={e => update('description', e.target.value)} /></label><div className="form-grid income-form-grid"><label>Valor<input required inputMode="decimal" placeholder="0,00" value={form.amount} onChange={e => update('amount', e.target.value)} /></label><label>Categoria<select required value={form.categoryId} onChange={e => update('categoryId', e.target.value)}>{categories.map(x => <option key={x.id} value={x.id}>{x.name}</option>)}</select></label></div><div className="form-grid recurring-form-grid"><label>Frequência<select value={form.frequency} onChange={e => update('frequency', e.target.value)}>{Object.entries(frequencyLabels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></label>{form.frequency === 'Monthly' && <label>Dia do mês<input type="number" min="1" max="31" value={form.dayOfMonth} onChange={e => update('dayOfMonth', e.target.value)} /></label>}<label>Data de início<input required type="date" value={form.startDate} onChange={e => update('startDate', e.target.value)} /></label><label>Data de término <span className="field-hint">(opcional)</span><input type="date" value={form.endDate} onChange={e => update('endDate', e.target.value)} /></label></div><p className="modal-copy">O dia 31 usa o último dia válido em meses menores. Previsões não alteram seu saldo real.</p><div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary">Salvar recorrência</button></div></form></div>
}

function IncomeModal({ categories, onClose, onSaved }) {
  const [form, setForm] = useState({ description: '', amount: '', categoryId: categories[0]?.id || '', date: new Date().toISOString().slice(0, 10) }); const [error, setError] = useState(''); const [saving, setSaving] = useState(false)
  const save = async event => { event.preventDefault(); const amount = parseAmount(form.amount); if (!form.description.trim()) return setError('Informe a descrição da entrada.'); if (!Number.isFinite(amount) || amount <= 0) return setError('Informe um valor maior que zero.'); if (!form.categoryId) return setError('Selecione uma categoria.'); setSaving(true); setError(''); try { await api.createIncome({ description: form.description.trim(), amount, date: form.date, categoryId: form.categoryId }); onSaved() } catch (e) { setError(errorText(e)) } finally { setSaving(false) } }
  return <div className="modal-backdrop"><form className="modal" onSubmit={save}><div className="modal-head"><div><span className="eyebrow">MOVIMENTAÇÃO</span><h2>Nova entrada</h2></div><button type="button" className="icon-button" onClick={onClose} aria-label="Fechar">×</button></div>{error && <div className="alert error">{error}</div>}<label>Descrição<input autoFocus required value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} /></label><label>Valor<input required inputMode="decimal" placeholder="0,00" value={form.amount} onChange={e => setForm({ ...form, amount: e.target.value })} /></label><div className="form-grid income-form-grid"><label>Categoria<select required value={form.categoryId} onChange={e => setForm({ ...form, categoryId: e.target.value })}>{categories.map(x => <option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label>Data<input required type="date" value={form.date} onChange={e => setForm({ ...form, date: e.target.value })} /></label></div><p className="modal-copy">Entradas não podem ser editadas depois de criadas. Se necessário, exclua e cadastre novamente.</p><div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary" disabled={saving}>Salvar entrada</button></div></form></div>
}

function CommitmentFilters({ search, setSearch, onOpenFilters, onCreateCategory }) {
  const [createOpen, setCreateOpen] = useState(false)
  return <><div className="filters-toolbar"><input aria-label="Pesquisar compromissos" placeholder="Pesquisar por nome..." value={search} onChange={e => setSearch(e.target.value)} /><button className="secondary mobile-filter-button" onClick={onOpenFilters}>Filtros</button><button className="secondary" onClick={() => setCreateOpen(true)}>Nova categoria</button></div>{createOpen && <CategoryCreateModal onClose={() => setCreateOpen(false)} onSaved={async name => { await onCreateCategory(name); setCreateOpen(false) }} />}</>
}

function FilterDrawer({ filters, setFilters, categories, onClear, onClose, onEditCategory, onDeleteCategory }) {
  const update = (key, value) => setFilters(current => ({ ...current, [key]: value }))
  return <div className="drawer-backdrop" onMouseDown={event => { if (event.target === event.currentTarget) onClose() }}><aside className="filter-drawer" role="dialog" aria-modal="true" aria-labelledby="filters-title"><div className="drawer-head"><div><span className="eyebrow">PERSONALIZE A LISTA</span><h2 id="filters-title">Filtros</h2></div><button className="icon-button" onClick={onClose} aria-label="Fechar filtros">×</button></div><div className="drawer-content"><fieldset><legend>Classificação</legend><label>Categoria<select value={filters.category} onChange={e => update('category', e.target.value)}><option value="">Todas as categorias</option>{categories.map(x => <option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label>Prioridade<select value={filters.priority} onChange={e => update('priority', e.target.value)}><option value="">Todas as prioridades</option><option value="1">Alta</option><option value="2">Média</option><option value="3">Baixa</option></select></label></fieldset><fieldset><legend>Situação</legend><label>Status<select value={filters.status} onChange={e => update('status', e.target.value)}><option value="">Todos os status</option><option value="active">Ativos</option><option value="completed">Concluídos</option></select></label><label>Cobertura<select value={filters.coverage} onChange={e => update('coverage', e.target.value)}><option value="">Todas as coberturas</option><option value="none">Sem reserva</option><option value="partial">Parcial</option><option value="next">Próxima parcela coberta</option><option value="full">Totalmente reservado</option></select></label><label>Pagamento<select value={filters.payment} onChange={e => update('payment', e.target.value)}><option value="">Todos os pagamentos</option><option value="none">Não iniciado</option><option value="progress">Em andamento</option><option value="done">Quitado</option></select></label></fieldset><fieldset><legend>Ordenação</legend><label>Ordenar por<select value={filters.sort} onChange={e => update('sort', e.target.value)}><option value="priority">Prioridade</option><option value="name">Nome</option><option value="total">Valor total</option><option value="remaining">Valor restante</option><option value="next">Próxima parcela</option><option value="progress">Progresso</option><option value="category">Categoria</option></select></label></fieldset><fieldset><legend>Filtros rápidos</legend><label className="filter-check"><input type="checkbox" checked={filters.deficit} onChange={e => update('deficit', e.target.checked)} /> Com déficit</label><label className="filter-check"><input type="checkbox" checked={filters.payable} onChange={e => update('payable', e.target.checked)} /> Aptos para pagar</label></fieldset><div className="category-tools">{categories.map(category => <span key={category.id}>{category.name}<button onClick={() => onEditCategory(category)} aria-label={`Editar ${category.name}`}>✎</button><button onClick={() => onDeleteCategory(category)} aria-label={`Excluir ${category.name}`}>×</button></span>)}</div></div><div className="drawer-actions"><button className="secondary" onClick={onClear}>Limpar filtros</button><button className="primary" onClick={onClose}>Aplicar filtros</button></div></aside></div>
}

function CategoryCreateModal({ onClose, onSaved }) { const [name, setName] = useState(''); const [error, setError] = useState(''); const save = async e => { e.preventDefault(); if (!name.trim()) { setError('Informe o nome da categoria.'); return } try { await onSaved(name.trim()) } catch (e) { setError(errorText(e)) } }; return <div className="modal-backdrop"><form className="modal" onSubmit={save}><h2>Nova categoria</h2>{error && <div className="alert error">{error}</div>}<label>Nome<input autoFocus value={name} onChange={e => setName(e.target.value)} /></label><div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary">Criar</button></div></form></div> }

function CommitmentCard({ item, availableBalance, categories, onChange, onEdit, onDelete }) {
  const [amount, setAmount] = useState(''); const [busy, setBusy] = useState(false); const [message, setMessage] = useState('')
  const coverage = item.remainingInstallments > 0 ? Math.min(100, item.allocatedAmount / item.installmentAmount * 100) : 100
  const paymentProgress = item.totalInstallments > 0 ? item.paidInstallments / item.totalInstallments * 100 : 100
  const mutate = async action => { setBusy(true); setMessage(''); try { await action(); setAmount(''); await onChange() } catch (e) { setMessage(errorText(e)) } finally { setBusy(false) } }
  const status = item.isCompleted ? ['Concluído', 'complete'] : item.isFullyCommitted ? ['Distribuição ativa', 'active'] : ['Manual', 'manual']
  const priority = item.priorityLabel || ['Indefinida', 'Alta', 'Média', 'Baixa'][item.priority]
  const nextDueDate = item.nextDueDate || addMonths(item.dueDate, item.paidInstallments)
  const missingForNext = Math.max(0, item.installmentAmount - item.allocatedAmount)
  return <article className="commitment-card">
    <header className="card-main"><div className="card-title"><div className="icon" aria-hidden="true">{item.name.slice(0, 1).toUpperCase()}</div><div className="card-heading"><div className="card-name-row"><h3 title={item.name}>{item.name}</h3><span className={`priority-badge priority-${item.priority}`}>{priority}</span></div><div className="card-meta">{item.categoryName || 'Sem categoria'}<span aria-hidden="true">·</span>{status[0]}</div></div></div><div className="card-actions"><button className="icon-button" onClick={onEdit} aria-label={`Editar ${item.name}`} title="Editar compromisso">✎</button><button className="icon-button danger-text" onClick={onDelete} aria-label={`Excluir ${item.name}`} title="Excluir compromisso">×</button></div></header>
    <div className="card-stats"><div><span>Valor total</span><strong>{money(item.totalAmount)}</strong></div><div><span>Reservado</span><strong>{money(item.allocatedAmount)}</strong></div><div><span>Próxima parcela</span><strong>{money(item.installmentAmount)}</strong></div><div><span>Parcelas</span><strong>{item.paidInstallments} / {item.totalInstallments} pagas</strong></div></div>
    <section className="progress-section coverage-section"><div className="progress-label"><span>Cobertura da próxima parcela</span><strong>{Math.round(coverage)}%</strong></div><div className="progress-row"><div className="progress-track"><div style={{ width: `${coverage}%` }} /></div></div><p className={`coverage-message ${coverage >= 100 ? 'is-covered' : ''}`}>{coverage >= 100 ? 'Próxima parcela totalmente coberta' : `Faltam ${money(missingForNext)} para cobrir a próxima parcela`}</p></section>
    <section className="progress-section commitment-progress"><div className="progress-label"><span>Progresso do compromisso</span><strong>{Math.round(paymentProgress)}%</strong></div><div className="total-progress"><strong>{item.paidInstallments} de {item.totalInstallments} parcelas pagas</strong><div className="mini-track"><div style={{ width: `${paymentProgress}%` }} /></div></div></section>
    <div className="card-footer"><section className="reserve-section"><span className="section-label">Reserva</span><div className="detail-row"><div><span>Reservado</span><strong>{money(item.allocatedAmount)}</strong></div><div><span>Restante</span><strong>{money(item.remainingAmount)}</strong></div></div><div className="allocation-form"><input type="number" min="0.01" step="0.01" placeholder="Valor" aria-label="Valor para reservar" value={amount} onChange={e => setAmount(e.target.value)} /><button disabled={busy || !amount || item.missingForFullCoverage <= 0} onClick={() => mutate(() => api.allocate(item.id, amount))}>Alocar</button><button className="secondary" disabled={busy || item.missingForFullCoverage <= 0 || availableBalance <= 0} onClick={() => mutate(() => api.allocate(item.id, Math.min(item.missingForFullCoverage, availableBalance)))}>Completar reserva</button><button className="tertiary withdraw-button" disabled={busy || !amount || item.allocatedAmount <= 0} onClick={() => mutate(() => api.deallocate(item.id, amount))}>Retirar</button></div></section><section className="payment-section"><span className="section-label">Próxima parcela</span><div className="payment-detail"><strong>{money(item.installmentAmount)}</strong><span>{formatDate(nextDueDate)}</span></div>{item.isCompleted ? <span className="payment-status">Compromisso concluído</span> : item.allocatedAmount >= item.installmentAmount ? <span className="payment-status payment-ready">✓ Reserva suficiente</span> : <span className="payment-status payment-hint">Faltam {money(missingForNext)}</span>}<button className="pay-button" disabled={busy || item.isCompleted || item.allocatedAmount < item.installmentAmount} onClick={() => mutate(() => api.payInstallment(item.id))}>Marcar parcela como paga</button></section></div>
    {message && <div className="inline-error">{message}</div>}
  </article>
}

function CommitmentModal({ item, categories, onClose, onSaved }) {
  const today = new Date().toISOString().slice(0, 10)
  const [form, setForm] = useState({ name: item.name || '', installmentAmount: item.installmentAmount || '', totalInstallments: item.totalInstallments || '', priority: item.priority || 1, categoryId: item.categoryId || '', isFullyCommitted: item.isFullyCommitted ?? true, dueDate: item.dueDate || today }); const [error, setError] = useState('')
  const previewAmount = parseAmount(form.installmentAmount); const previewInstallments = Number(form.totalInstallments); const previewLastDate = form.dueDate && Number.isInteger(previewInstallments) && previewInstallments > 0 ? addMonths(form.dueDate, previewInstallments - 1) : ''
  const save = async e => { e.preventDefault(); setError(''); const installmentAmount = parseAmount(form.installmentAmount); const totalInstallments = Number(form.totalInstallments); if (!form.name.trim()) return setError('Informe o nome do compromisso.'); if (!Number.isFinite(installmentAmount) || installmentAmount <= 0) return setError('Informe um valor de parcela válido, como 0,05.'); if (!Number.isInteger(totalInstallments) || totalInstallments <= 0) return setError('Informe o total de parcelas.'); if (!form.dueDate) return setError('Informe o primeiro vencimento.'); const payload = { name: form.name.trim(), installmentAmount, totalInstallments, priority: Number(form.priority), isFullyCommitted: form.isFullyCommitted, categoryId: form.categoryId || null, dueDate: form.dueDate }; try { if (item.id) await api.updateCommitment(item.id, payload); else await api.createCommitment(payload); onSaved() } catch (e) { setError(errorText(e)) } }
  return <div className="modal-backdrop"><form className="modal" onSubmit={save}><div className="modal-head"><div><span className="eyebrow">COMPROMISSO</span><h2>{item.id ? 'Editar compromisso' : 'Novo compromisso'}</h2></div><button type="button" className="icon-button" onClick={onClose}>×</button></div>{error && <div className="alert error">{error}</div>}<label>Nome<input required value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} /></label><div className="form-grid"><label>Valor da parcela<input required inputMode="decimal" placeholder="0,05" value={form.installmentAmount} onChange={e => setForm({ ...form, installmentAmount: e.target.value })} /></label><label>Total de parcelas<input required inputMode="numeric" value={form.totalInstallments} onChange={e => setForm({ ...form, totalInstallments: e.target.value.replace(/\D/g, '') })} /></label><label>Prioridade<select required value={form.priority} onChange={e => setForm({ ...form, priority: Number(e.target.value) })}><option value="1">Alta</option><option value="2">Média</option><option value="3">Baixa</option></select></label><label>Categoria<select value={form.categoryId || ''} onChange={e => setForm({ ...form, categoryId: e.target.value || null })}><option value="">Sem categoria</option>{categories.map(x => <option key={x.id} value={x.id}>{x.name}</option>)}</select></label></div><label>Primeiro vencimento<input required type="date" value={form.dueDate} onChange={e => setForm({ ...form, dueDate: e.target.value })} /><span className="field-hint">A primeira parcela será cobrada nesta data.</span></label>{Number.isFinite(previewAmount) && previewAmount > 0 && Number.isInteger(previewInstallments) && previewInstallments > 0 && form.dueDate && <div className="preview-list"><strong>Parcelamento</strong><span>{previewInstallments}x de {money(previewAmount)}</span><small>Primeira: {formatDate(form.dueDate)} · Última: {formatDate(previewLastDate)}</small></div>}<label className="check"><input type="checkbox" checked={form.isFullyCommitted} onChange={e => setForm({ ...form, isFullyCommitted: e.target.checked })} /> Participa da distribuição automática</label><div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary">Salvar compromisso</button></div></form></div>
}

function DistributionModal({ preview, onClose, onConfirm }) { return <div className="modal-backdrop"><div className="modal"><div className="modal-head"><div><span className="eyebrow">SIMULAÇÃO</span><h2>Distribuir saldo?</h2></div><button className="icon-button" onClick={onClose}>×</button></div><p className="modal-copy">O Aloca vai reservar <strong>{money(preview?.wouldAllocate)}</strong> seguindo a prioridade dos compromissos ativos.</p><div className="preview-list">{preview?.allocations?.length ? preview.allocations.map(x => <div key={x.financialCommitmentId}><span>{x.name}</span><strong>{money(x.amount)}</strong></div>) : <div className="empty small">Nenhuma nova alocação necessária.</div>}</div><div className="preview-total"><span>Saldo livre após</span><strong>{money(preview?.remainingFreeBalance)}</strong></div><div className="modal-actions"><button className="secondary" onClick={onClose}>Cancelar</button><button className="primary" onClick={onConfirm} disabled={!preview?.wouldAllocate}>Confirmar distribuição</button></div></div></div> }

createRoot(document.getElementById('root')).render(<App />)
